    print("[*] Crafting malicious ClientHello with mismatched parameters...")
    # Mismatch ALPN and Cipher Suite
    mismatch_alpn = "h2" # Different from original
    mismatch_cipher = 0x1302 # TLS_AES_256_GCM_SHA384 (Different from original)
    
